use super::*;
#[test]
fn actual_original_decoder_receipt_closes_only_on_distinct_paid_metadata_turns(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let quantum=RetainedCloneGrant{maximum_items:1,..stock};
 let mut caller=semio_framework_job_testing_caller::OriginalJobFixtureCaller::admit(semio_framework_job_context::OperationId(row["operation"].as_u64().unwrap()),semio_framework_job_context::Generation(row["generation"].as_u64().unwrap()),stock,||Some(1),u64::MAX,s["fuel"].as_u64().unwrap());let mut owner=OriginalJobDecodeOwner::empty();
 let value=caller.turn_with_decoder(quantum,&mut owner,|cx|{let value=cx.with_native_receiving(|_|Ok::<_,ValueError>(17u64))?;cx.consume_fuel(1);Ok(value)}).unwrap();assert_eq!(serde_json::to_value(value).unwrap(),row["value"]);let identity=owner.receiving_identity();assert!(identity.is_some());assert!(!owner.closing);
 let denied=owner.close_step(Default::default());assert_eq!(denied.work,row["deniedWork"].as_u64().unwrap());assert_eq!(denied.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(owner.receiving_identity(),identity);assert!(!owner.closing);
 let mut work=Vec::new();
 for _ in 0..s["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break;}let demand=owner.retirement_demands(quantum.maximum_copy_bytes).unwrap();let units=caller.turn(quantum,|cx|{let mut units=0;semio_framework_job_context::close_original_retained_step(cx,demand,|actual|{let turn=owner.close_step(actual);units=turn.work;assert_eq!(turn.result.as_ref().unwrap().progress().copied_bytes,0);turn})?;Ok(units)}).unwrap();work.push(units);}
 assert!(owner.terminal_is_empty());assert_eq!(serde_json::to_value(work).unwrap(),row["work"]);let cached=owner.close_step(Default::default());assert_eq!(cached.work,row["cachedWork"].as_u64().unwrap());assert_eq!(cached.result.unwrap().progress(),RetainedCloneProgress::default());drop(owner);caller.retire(stock);
}
